package com.medsimple.wearable.entity;

/**
 * Provenance of a wearable reading. Stored on every row and surfaced to the physician so consumer
 * patient-generated data is never mistaken for a clinical-grade measurement.
 */
public enum WearableSource {
    /** A patient or staff member typed the reading in. */
    MANUAL,
    /** Generated by the fallback adapter for development / demo (no real device). */
    SYNTHETIC,
    /** Received from a real wearable aggregator (Terra / Validic / ...) — Phase 2. */
    AGGREGATOR
}
